window.__POLYGON_STYLE_PATCH__ = "    .unit-editor-shell {\n      position: relative;\n      height: 100%;\n      min-height: 0;\n      display: flex;\n      flex-direction: column;\n      background: rgba(250,249,244,.72);\n    }\n    .unit-editor-toolbar {\n      position: relative;\n      z-index: 8;\n      flex: 0 0 auto;\n      display: grid;\n      grid-template-columns: 30px auto minmax(0,1fr);\n      gap: 5px;\n      align-items: center;\n      min-height: 43px;\n      padding: 6px 8px;\n      border-bottom: 1px solid var(--line);\n      background: #ecebe3;\n      box-shadow: 0 2px 7px rgba(30,34,24,.08);\n    }\n    .unit-editor-toolbar .small-button,\n    .unit-editor-toolbar .action-button { min-height: 29px; display: inline-flex; align-items: center; justify-content: center; gap: 4px; padding: 5px 7px; font-size: 10px; white-space: nowrap; }\n    .unit-editor-toolbar .action-button { justify-self: stretch; }\n    .unit-editor-scroll { min-height: 0; flex: 1; overflow: auto; padding: 8px; }\n    .unit-editor-empty { display: grid; place-items: center; min-height: 230px; padding: 18px; text-align: center; color: var(--muted); }\n    .unit-editor-empty strong { display: block; color: var(--ink); font-size: 12px; margin-bottom: 4px; }\n    .unit-editor-empty p { max-width: 240px; margin: 0 0 12px; font-size: 10px; line-height: 1.45; }\n    .unit-card-head { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }\n    .unit-card-avatar { width: 31px; height: 31px; display: grid; place-items: center; border-radius: 50%; background: #dce6e8; border: 1px solid #57747f; font-size: 10px; font-weight: 900; }\n    .unit-card-copy { min-width: 0; flex: 1; }\n    .unit-card-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; font-weight: 900; }\n    .unit-card-meta { margin-top: 2px; color: var(--muted); font-size: 9px; }\n    .unit-quick-actions { display: flex; flex-wrap: wrap; gap: 4px; }\n    .icon-tool {\n      width: 29px;\n      height: 29px;\n      display: inline-grid;\n      place-items: center;\n      flex: 0 0 auto;\n      border: 1px solid var(--line-strong);\n      border-radius: 4px;\n      background: #fff;\n      color: #3d4038;\n      padding: 0;\n    }\n    .icon-tool:hover { background: #eceae0; border-color: #85897d; }\n    .icon-tool.is-active { background: var(--accent-soft); border-color: #9d8832; color: #393214; box-shadow: inset 0 0 0 1px rgba(157,136,50,.18); }\n    .icon-tool--danger { color: var(--danger); }\n    .icon-tool svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n    .compact-section { margin-bottom: 8px; border: 1px solid var(--line); border-radius: 5px; background: rgba(255,255,255,.84); overflow: hidden; }\n    .compact-section__head { min-height: 29px; display: flex; align-items: center; justify-content: space-between; gap: 7px; padding: 5px 8px; border-bottom: 1px solid var(--line); background: #efeee7; }\n    .compact-section__title { font-size: 10px; font-weight: 900; letter-spacing: .04em; text-transform: uppercase; }\n    .compact-section__body { padding: 7px; }\n    .compact-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 6px; }\n    .compact-grid--three { grid-template-columns: repeat(3, minmax(0,1fr)); }\n    .compact-field { display: grid; gap: 3px; min-width: 0; }\n    .compact-field--wide { grid-column: 1 / -1; }\n    .compact-field label { color: #62655d; font-size: 9px; font-weight: 800; }\n    .compact-field input,\n    .compact-field select {\n      width: 100%;\n      min-width: 0;\n      height: 28px;\n      border: 1px solid var(--line-strong);\n      border-radius: 4px;\n      background: #fff;\n      padding: 4px 6px;\n      font-size: 10px;\n    }\n    .pose-tools { display: flex; gap: 4px; }\n    .pose-tools .icon-tool { width: 31px; }\n    .compact-summary { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 8px; align-items: center; min-height: 28px; font-size: 10px; }\n    .compact-summary + .compact-summary { border-top: 1px solid var(--line); }\n    .compact-summary strong { font-size: 10px; text-align: right; }\n    .compact-muted { color: var(--muted); font-size: 9px; line-height: 1.35; }\n    .unit-list-popover {\n      position: absolute;\n      z-index: 12;\n      top: 47px;\n      left: 7px;\n      right: 7px;\n      max-height: min(520px, calc(100% - 56px));\n      display: flex;\n      flex-direction: column;\n      padding: 7px;\n      border: 1px solid var(--line-strong);\n      border-radius: 6px;\n      background: var(--panel-solid);\n      box-shadow: 0 16px 40px rgba(22,26,17,.24);\n    }\n    .unit-list-popover__head { display: flex; align-items: center; gap: 6px; margin-bottom: 6px; }\n    .unit-list-popover__head strong { flex: 1; font-size: 11px; }\n    .unit-list-search { width: 100%; height: 29px; margin-bottom: 6px; border: 1px solid var(--line-strong); border-radius: 4px; padding: 4px 7px; font-size: 10px; }\n    .unit-list-popover__body { min-height: 0; overflow: auto; display: grid; gap: 5px; }\n    .unit-list-popover .unit-row { min-height: 38px; padding: 5px 7px; }\n    .unit-list-popover .unit-row__icon { width: 24px; height: 24px; }\n    .unit-list-empty { padding: 18px 8px; text-align: center; color: var(--muted); font-size: 10px; }\n    .profile-set-note { margin-top: 5px; padding: 5px 6px; border-left: 2px solid var(--accent); background: #f5f1dc; color: #665f3f; font-size: 9px; line-height: 1.35; }\n\n    .modal--unit { width: min(980px, 95vw); max-height: 90vh; }\n    .modal--unit .modal__head { min-height: 50px; padding: 8px 11px 8px 14px; }\n    .modal--unit .modal__title { font-size: 15px; }\n    .modal--unit .modal__close { width: 30px; height: 30px; }\n    .modal--unit .modal__footer { min-height: 48px; padding: 7px 11px; }\n    .unit-details-layout { display: grid; grid-template-columns: 176px minmax(0,1fr); min-height: 520px; }\n    .unit-details-nav { padding: 8px; border-right: 1px solid var(--line); background: #ecebe3; }\n    .unit-details-nav button { width: 100%; min-height: 32px; margin-bottom: 4px; padding: 6px 8px; border: 0; border-radius: 4px; background: transparent; text-align: left; font-size: 10px; font-weight: 800; }\n    .unit-details-nav button:hover { background: #dfded6; }\n    .unit-details-nav button.is-active { background: var(--top); color: #fff; }\n    .unit-details-main { min-width: 0; overflow: auto; padding: 12px; }\n    .unit-details-main .compact-section { max-width: 720px; }\n    .unit-detail-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 8px; }\n    .unit-detail-grid--three { grid-template-columns: repeat(3,minmax(0,1fr)); }\n    .profile-readonly { margin-top: 7px; border: 1px solid var(--line); border-radius: 4px; overflow: hidden; }\n    .profile-readonly summary { cursor: pointer; padding: 7px 8px; background: #f0efe8; font-size: 10px; font-weight: 800; }\n    .profile-readonly dl { margin: 0; padding: 4px 8px 8px; }\n    .profile-readonly .data-row { padding: 6px 0; font-size: 10px; }\n    .unit-coordinate-row { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 6px; }\n    .unit-details-hint { margin-top: 7px; color: var(--muted); font-size: 9px; line-height: 1.4; }\n    @media (max-width: 760px) {\n      .unit-details-layout { grid-template-columns: 1fr; }\n      .unit-details-nav { display: flex; gap: 4px; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--line); }\n      .unit-details-nav button { width: auto; white-space: nowrap; margin: 0; }\n      .unit-detail-grid, .unit-detail-grid--three { grid-template-columns: 1fr; }\n    }\n\n";
